async function adminReports(){try{const [e,p,po]=await Promise.all([api('adminEmployees'),api('adminProjects'),api('adminProjectOptions',{year:new Date().getFullYear()})]);adminShell('BÁO CÁO',`<div class="card"><div class="field"><label>Nhóm báo cáo</label><select id="rp_kind" onchange="syncReportDateField()"><option value="EMPLOYEE">BÁO CÁO THEO NHÂN VIÊN</option><option value="PROJECT">BÁO CÁO THEO CÔNG TRÌNH</option></select></div><div id="rp_employee_filters"><div class="two"><div class="field"><label>Loại báo cáo</label><select id="rp_mode" onchange="syncReportDateField()"><option value="MONTH">THÁNG</option><option value="DAY">NGÀY</option></select></div><div class="field"><label>Nhân viên</label><select id="rp_emp"><option value="ALL">Tất cả nhân viên</option>${e.rows.map(x=>`<option value="${esc(x.EMPLOYEE_ID)}">${esc(x.NAME)} — ${esc(x.EMPLOYEE_ID)}</option>`).join('')}</select></div></div></div><div class="field"><label id="rp_date_label">Tháng báo cáo</label><input id="rp_date" type="month" value="${localMonth()}" onchange="refreshProjectReportOptions()"></div><div class="field" id="rp_project_filter" style="display:none"><label>Công trình</label><select id="rp_project"><option value="ALL">Tất cả công trình</option>${p.rows.map(x=>`<option value="${esc(x.PROJECT_ID)}">${esc(x.PROJECT_NAME)}</option>`).join('')}</select></div><div class="section-actions"><button class="btn blue" onclick="loadReport()">XEM BÁO CÁO</button></div><div id="reportArea">Chọn điều kiện rồi xem báo cáo.</div></div>`);window._reportProjects=p.rows||[];syncReportDateField()}catch(e){toast(e.message)}}
async function refreshProjectReportOptions(){if(($('rp_kind')?.value||'')!=='PROJECT')return;const year=Number($('rp_date')?.value||new Date().getFullYear()),select=$('rp_project');if(!select)return;const keep=select.value;try{const j=await api('adminProjectOptions',{year});select.innerHTML='<option value="ALL">Tất cả công trình</option>'+(j.rows||[]).map(x=>`<option value="${esc(x.PROJECT_ID)}">${esc(x.PROJECT_NAME)}</option>`).join('');if(Array.from(select.options).some(o=>o.value===keep))select.value=keep}catch(e){toast(e.message)}}
function syncReportDateField(){const kind=$('rp_kind')?.value||'EMPLOYEE',mode=$('rp_mode')?.value||'MONTH',i=$('rp_date'),l=$('rp_date_label'),filters=$('rp_employee_filters');if(!i)return;if(filters)filters.style.display=kind==='PROJECT'?'none':'';const pf=$('rp_project_filter');if(pf)pf.style.display=kind==='PROJECT'?'block':'none';if(kind==='PROJECT'){i.type='number';i.min='2000';i.max='2100';i.step='1';i.value=String(new Date().getFullYear());if(l)l.textContent='Năm báo cáo'}else if(mode==='DAY'){i.type='date';i.value=localDate();if(l)l.textContent='Ngày báo cáo'}else{i.type='month';i.value=localMonth();if(l)l.textContent='Tháng báo cáo'}}
async function loadReport(){try{const kind=$('rp_kind')?.value||'EMPLOYEE',date=$('rp_date').value;if(kind==='PROJECT'){const selectedProject=$('rp_project')?.value||'ALL';const j=await api('adminReports',{mode:'PROJECT',year:Number(date),projectId:selectedProject});const projects=j.rows||[];$('reportArea').innerHTML=`<div class="report-print"><div class="report-heading compact"><div class="report-row r1">CUATUNG LIGHTING</div><div class="report-row r2">BÁO CÁO TỔNG CÔNG THEO CÔNG TRÌNH</div><div class="report-row r3">Năm ${esc(String(j.year))} · ${esc(selectedProject==='ALL'?'Tất cả công trình':($('rp_project')?.selectedOptions[0]?.textContent||selectedProject))}</div></div><div class="report-summary"><span><b>${esc(String(j.summary?.workDays||0))}</b> tổng công theo lựa chọn</span></div><div class="table-wrap"><table class="table report-table"><thead><tr><th>STT</th><th>Mã công trình</th><th>Tên công trình</th><th>Tổng công trong năm</th></tr></thead><tbody>${projects.length?projects.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.PROJECT_ID)}</td><td>${esc(x.PROJECT_NAME)}</td><td><b>${esc(String(x.WORK_DAYS||0))}</b></td></tr>`).join(''):'<tr><td colspan="4">Không có dữ liệu công trong năm này.</td></tr>'}</tbody></table></div></div><div class="section-actions no-print"><button class="btn green" onclick="window.print()">XUẤT / IN A4</button><button class="btn blue" onclick="downloadCSV()">XUẤT EXCEL</button></div>`;window._reportRows=projects;window._reportMode='PROJECT';window._reportYear=j.year;return}const mode=$('rp_mode').value,p={mode,employeeId:$('rp_emp').value};if(mode==='DAY')p.date=date;else p.month=date.slice(0,7);const j=await api('adminReports',p);if(mode==='MONTH'&&$('rp_emp').value!=='ALL'){await loadAdminEmployeeMonthDetail($('rp_emp').value,j.month);return}const title=mode==='DAY'?'BÁO CÁO CHẤM CÔNG THEO NGÀY':'BÁO CÁO CÔNG THÁNG',filter=$('rp_emp').value==='ALL'?'Tất cả nhân viên':$('rp_emp').selectedOptions[0]?.textContent||'',h=j.header||{},headers=[h.HEADER_1||'Cuatung Lighting',h.HEADER_2||title,h.HEADER_3||(mode==='DAY'?'Ngày '+j.date:'Tháng '+j.month),h.HEADER_4||filter];$('reportArea').innerHTML=`<div class="report-print"><div class="report-heading compact"><div class="report-row r1">${esc(headers[0])}</div><div class="report-row r2">${esc(headers[1])}</div><div class="report-row r3">${esc(headers[2])}</div><div class="report-row r4">${esc(headers[3])}</div></div><div class="report-summary">${mode==='MONTH'?`<span><b>${j.summary?.workDays??0}</b> ngày công</span><span><b>${j.summary?.hours??0}</b> giờ</span>`:`<span><b>${j.rows.length}</b> lượt công</span>`}</div><div class="table-wrap"><table class="table report-table"><thead><tr>${mode==='DAY'?'<th>Mã</th><th>Họ tên</th><th>Công trình</th><th>Ca</th><th>Vào</th><th>Ra</th><th>Giờ</th><th>TT</th>':'<th>Mã</th><th>Họ tên</th><th>Ngày công</th><th>Giờ</th><th>Phép</th><th>Muộn</th><th>Sớm</th>'}</tr></thead><tbody>${j.rows.map(x=>mode==='DAY'?`<tr><td>${esc(x.EMPLOYEE_ID)}</td><td>${esc(x.NAME)}</td><td>${esc(projectName(x.PROJECT_ID))}</td><td>${esc(shiftName(x.SHIFT_ID))}</td><td>${esc(x.CHECKIN_TIME)}</td><td>${esc(x.CHECKOUT_TIME)}</td><td>${x.WORK_HOURS}</td><td>${esc(x.STATUS)}</td></tr>`:`<tr><td>${esc(x.EMPLOYEE_ID)}</td><td><button type="button" class="report-employee-link" data-report-employee="${esc(x.EMPLOYEE_ID)}" data-report-month="${esc(String(j.month||date.slice(0,7)))}">${esc(x.NAME)}</button></td><td>${x.WORK_DAYS}</td><td>${x.HOURS}</td><td>${x.LEAVE}</td><td>${x.LATE}</td><td>${x.EARLY}</td></tr>`).join('')}</tbody></table></div></div><div class="section-actions no-print"><button class="btn green" onclick="window.print()">XUẤT / IN A4</button><button class="btn blue" onclick="downloadCSV()">XUẤT EXCEL</button></div>`;window._reportRows=j.rows;window._reportMode=mode;document.querySelectorAll('[data-report-employee]').forEach(b=>b.addEventListener('click',()=>loadAdminEmployeeMonthDetail(b.dataset.reportEmployee,b.dataset.reportMonth)))}catch(e){toast(e.message)}}

async function loadAdminEmployeeMonthDetail(employeeId,month){
  try{
    const j=await api('adminEmployeeMonthDetail',{employeeId,month});
    const rows=j.grouped||[];
    const total=j.summary||{};
    const back=`<button type="button" class="btn light" onclick="backToEmployeeReport()">← QUAY LẠI BÁO CÁO THÁNG</button>`;
    const days=rows.length?rows.map(d=>`<details class="report-detail-day" open>
      <summary><span>Ngày ${esc(formatVNDate(d.date))}</span><b>${esc(String(d.workDays||0))} công</b></summary>
      <div class="report-detail-list">${d.rows.map(x=>`<div class="report-detail-row">
        <div class="report-detail-main"><b>${esc(x.SHIFT_NAME||x.SHIFT_PART||'Ca')}</b><span>${esc(x.PROJECT_NAME||x.PROJECT_ID||'')}</span></div>
        <div class="report-detail-meta"><span>${esc(String(x.WORK_DAYS||0))} công</span><span>${esc(String(x.WORK_HOURS||0))} giờ</span>${x.STATUS?`<span>${esc(x.STATUS==='APPROVED'?'Đã duyệt':x.STATUS)}</span>`:''}</div>
      </div>`).join('')}</div>
    </details>`).join(''):'<div class="empty">Chưa có ngày công được duyệt trong tháng này.</div>';
    const leaves=(j.leaves||[]).length?`<div class="report-leave-box"><h3>Ngày phép</h3>${j.leaves.map(x=>`<div class="report-leave-row"><b>${esc(formatVNDate(x.WORK_DATE))}</b><span>${esc(x.SHIFT||x.TYPE||'')}</span><span>${esc(x.REASON||'')}</span></div>`).join('')}</div>`:'';
    const area=$('reportArea');
    if(!area)return;
    area.innerHTML=`<div class="report-detail-head">${back}<h2>${esc(j.name||employeeId)}</h2><p>Chi tiết ngày công tháng ${esc(formatMonthVN(j.month))}</p></div>
      <div class="report-summary"><span><b>${esc(String(total.workDays||0))}</b> ngày công</span><span><b>${esc(String(total.hours||0))}</b> giờ</span><span><b>${esc(String(total.leave||0))}</b> ngày phép</span><span><b>${esc(String(total.late||0))}</b> đi muộn</span><span><b>${esc(String(total.early||0))}</b> về sớm</span></div>
      <div class="report-detail-month">${days}</div>${leaves}`;
  }catch(e){const area=$('reportArea');if(area){area.innerHTML=`<div class="error-card">Không tải được báo cáo chi tiết: ${esc(e.message)} <button type="button" class="btn light" data-retry-employee="${esc(employeeId)}" data-retry-month="${esc(month)}">THỬ LẠI</button></div>`;const b=area.querySelector('[data-retry-employee]');if(b)b.addEventListener('click',()=>loadAdminEmployeeMonthDetail(b.dataset.retryEmployee,b.dataset.retryMonth))}toast(e.message)}
}

function downloadCSV(){
  const rows=window._reportRows||[],mode=window._reportMode;
  if(!mode){toast('Vui lòng xem báo cáo trước khi xuất.');return}
  let head,data,title,file;
  if(mode==='PROJECT'){
    head=['STT','Mã công trình','Tên công trình','Tổng công trong năm'];
    data=rows.map((x,i)=>[i+1,x.PROJECT_ID,x.PROJECT_NAME,x.WORK_DAYS]);
    title='BÁO CÁO TỔNG CÔNG THEO CÔNG TRÌNH NĂM '+window._reportYear;
    file='bao-cao-cong-trinh-'+window._reportYear+'.csv';
  }else{
    head=mode==='DAY'?['Mã nhân viên','Họ và tên','Công trình','Ca làm','Giờ vào','Giờ ra','Số giờ làm','Trạng thái']:['Mã nhân viên','Họ và tên','Ngày công','Tổng số giờ','Ngày phép','Đi muộn','Về sớm'];
    data=rows.map(x=>mode==='DAY'?[x.EMPLOYEE_ID,x.NAME,projectName(x.PROJECT_ID),shiftName(x.SHIFT_ID),x.CHECKIN_TIME,x.CHECKOUT_TIME,x.WORK_HOURS,x.STATUS]:[x.EMPLOYEE_ID,x.NAME,x.WORK_DAYS,x.HOURS,x.LEAVE,x.LATE,x.EARLY]);
    title=mode==='DAY'?'BÁO CÁO CHẤM CÔNG THEO NGÀY':'BÁO CÁO CÔNG THÁNG';
    file=mode==='DAY'?'bao-cao-cham-cong-ngay.csv':'bao-cao-cong-thang.csv';
  }
  const safe=v=>{let x=String(v??'');if(/^[\s]*[=+@]/.test(x)||/^[\s]*-/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"'};
  const csv='\uFEFF'+[ [title], head, ...data ].map(r=>r.map(safe).join(',')).join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));
  const a=document.createElement('a');a.href=url;a.download=file;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
async function adminLogs(){try{const j=await api('adminLogs');adminShell('NHẬT KÝ',`<div class="section-actions"><button class="btn blue" onclick="runAdminDataAudit()">KIỂM TRA ĐỘ NHẤT QUÁN</button><button class="btn light" onclick="downloadApiTiming()">XUẤT NHẬT KÝ TỐC ĐỘ</button></div><div id="dataAuditArea"></div><div class="card table-wrap"><table class="table"><thead><tr><th>Thời gian</th><th>Action</th><th>User</th><th>Chi tiết</th></tr></thead><tbody>${j.rows.slice().reverse().map(x=>`<tr><td>${esc(x.TIME)}</td><td>${esc(x.ACTION)}</td><td>${esc(x.USER_ID)}</td><td>${esc(x.DETAIL)}</td></tr>`).join('')}</tbody></table></div>`)}catch(e){toast(e.message)}}
async function runAdminDataAudit(){const area=$('dataAuditArea');if(area)area.innerHTML='<div class="card">Đang đối chiếu dữ liệu chỉ đọc…</div>';try{const j=await api('adminDataAudit');const c=j.counts||{},issues=j.issues||[];if(area)area.innerHTML=`<div class="card"><h2>KẾT QUẢ KIỂM TRA</h2><p>Phiên bản ${esc(j.version)} · ${esc(String(j.issueCount))} vấn đề phát hiện · Không thay đổi dữ liệu.</p><div class="report-summary"><span>${c.employees||0} nhân viên</span><span>${c.projects||0} công trình</span><span>${c.shifts||0} ca</span><span>${c.attendance||0} bản ghi công</span><span>${c.assignments||0} phân công</span><span>${c.notifications||0} thông báo</span></div>${issues.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Loại lỗi</th><th>Sheet / khóa</th><th>Chi tiết</th></tr></thead><tbody>${issues.map(x=>`<tr><td>${esc(x.type||'')}</td><td>${esc(x.sheet||x.key||x.assignmentId||'')}</td><td>${esc(JSON.stringify(x))}</td></tr>`).join('')}</tbody></table></div>`:'<p>Không phát hiện lỗi nhất quán theo các kiểm tra hiện có.</p>'}</div>`}catch(e){if(area)area.innerHTML=`<div class="card error-card">Không kiểm tra được: ${esc(e.message)}</div>`;toast(e.message)}}
function downloadApiTiming(){let rows=[];try{rows=JSON.parse(LS.getItem('cl_api_timing')||'[]')}catch(e){}if(!rows.length)return toast('Chưa có nhật ký tốc độ. Hãy thao tác thử các chức năng trước.');const blob=new Blob([JSON.stringify(rows,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cuatung-api-timing.json';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Đã xuất nhật ký tốc độ.')}
function projectName(id){const s=String(id||'');if(s.startsWith('OTHER:')){try{return decodeURIComponent(s.slice(6))}catch(e){return s.slice(6)}}return S.projects.find(x=>String(x.PROJECT_ID)===s)?.PROJECT_NAME||s}function shiftName(id){return S.shifts.find(x=>String(x.SHIFT_ID)===String(id))?.SHIFT_NAME||id}
function showChangePassword(force){adminShell('ĐỔI MẬT KHẨU',`<div class="card"><p>${force?'Tài khoản phải đổi mật khẩu trước khi tiếp tục.':''}</p><div class="field"><label>Mật khẩu mới</label><input id="cp1" type="password"></div><div class="field"><label>Nhập lại</label><input id="cp2" type="password"></div><button class="btn blue full" onclick="changePassword()">ĐỔI MẬT KHẨU</button></div>`)}
async function changePassword(){if($('cp1').value!==$('cp2').value)return toast('Hai mật khẩu không khớp.');try{await api('changePassword',{newPassword:$('cp1').value});await bootstrap();showHome()}catch(e){toast(e.message)}}
function requestLogout(){$('modalTitle').textContent='ĐĂNG XUẤT';$('modalText').textContent='Bạn có chắc muốn đăng xuất khỏi tài khoản này?';$('modalCancel').textContent='HỦY';$('modalOk').textContent='ĐĂNG XUẤT';$('modal').classList.remove('hidden');$('modalOk').onclick=async()=>{ $('modal').classList.add('hidden'); await doLogout() };$('modalCancel').onclick=()=>{$('modal').classList.add('hidden')}} 
async function doLogout(){try{if(token)await api('logout')}catch(e){}clearSession();renderLogin()}
async function restore(){
  renderLogin();if(!token||!me)return;const snap=readSnapshot();
  if(snap&&Date.now()-snap.at<10*60*1000)applyBootstrap(snap.data);
  showHome();showUnread();
  bootstrap().then(()=>{saveSnapshot(S);if(screen==='userHome'||screen==='adminHome')showHome();showUnread()}).catch(e=>{if(/phiên đăng nhập|không hợp lệ|hết hạn/i.test(e.message)){clearSession();renderLogin()}else{setNet(false);toast('Đang sử dụng dữ liệu đã lưu. Khi có mạng sẽ cập nhật.')}})
}
